#!/usr/bin/env bash
# Question 1: Scale StatefulSet ${Q1_STS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/sts
mkdir -p /opt/course/sts
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete statefulset "${Q1_STS}" --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q1_NS}" delete service "${Q1_STS}-hl" --ignore-not-found >/dev/null
kubectl -n "${Q1_NS}" wait --for=delete pod -l app="${Q1_STS}" --timeout=90s >/dev/null 2>&1 || true
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: Service
metadata: { name: ${Q1_STS}-hl, namespace: ${Q1_NS} }
spec:
  selector: { app: ${Q1_STS} }
  ports: [{ port: 80 }]
---
apiVersion: apps/v1
kind: StatefulSet
metadata: { name: ${Q1_STS}, namespace: ${Q1_NS} }
spec:
  serviceName: ${Q1_STS}-hl
  replicas: 2
  selector: { matchLabels: { app: ${Q1_STS} } }
  template:
    metadata: { labels: { app: ${Q1_STS} } }
    spec:
      containers: [{ name: nginx, image: nginx:1.27-alpine, ports: [{ containerPort: 80 }] }]
EOF
kubectl -n "${Q1_NS}" rollout status "statefulset/${Q1_STS}" --timeout=180s >/dev/null
: "${Q1_NS}" "${Q1_STS}" "${Q1_DS}"
